  "io": "POT VR1 ad=1 val=50 label=설정 볼륨\nTANK TK1 in=P00025 out=P00026 hi=P00012 lo=P00013 ad=3 level=20 label=물탱크\nLAMP HIL P00020 color=red label=상한 경보\nLAMP LOL P00021 color=yellow label=하한 경보\nBUZ AL1 P0002F label=경보 부저",
  "program": "; CH3 = 물탱크 수위\nLOAD P00041\nMOV U02.02 D00000\nLOAD F00099\nDIV D00000 160 D00002\n\n; 30 % 미만이면 급수 밸브\nLOAD< D00002 30\nOUT P00025\n\n; 80 % 를 넘으면 배수 밸브\nLOAD> D00002 80\nOUT P00026\n\n; 10 % 미만 또는 85 % 초과면 경보\nLOAD< D00002 10\nOR> D00002 85\nOUT P0002F\nEND",
