  "test": "OV1=50 scan=3 -> D00002~50 D00004~10 D00008>3000 D00008<3800 MTR1~20\nOV1=20 scan=3 -> D00004~40 D00008~12800 MTR1~80\nOV1=59 scan=3 -> D00008>0 D00008<1000 MTR1<6\nOV1=65 scan=3 -> D00008=0 MTR1=0",
  "monitor": "D00002 D00004 D00008 U03.00"
